export const SCENE_ASSET_ALIASES: Record<string, string> = {
  // Officer stage portrait aliases (Lua X.ART_ALT)
  dk_stage_e3: 'dk_int_e5',
  dk_stage_l3: 'dk_int_l5',
  dk_stage_v3: 'dk_int_v5',
  // Floor combat & card fallbacks
  dk_fl_fighter: 'dk_fl_display',
  dk_base_load: 'dk_base_cont',
  dk_base_raid_: 'dk_base_raid',
  // Estate & War unbundled key fallbacks
  dk_act_granary: 'dk_act_farm',
  dk_act_farm: 'dk_fac_farmland',
  dk_fac_torture: 'dk_fac_prison',
  dk_fac_prison: 'dk_fac_annex',
  dk_war_raid: 'dk_exd_raid',
  // Expedition expansion region aliases (v1.13.0)
  dk_exr_hotspring: 'dk_exr_road',
  dk_exr_market: 'dk_exd_village',
  hotspring: 'dk_exr_road',
  market: 'dk_exd_village',
  // Ending <-> Game Over / Event aliases (Lua X.ART_ALT)
  dk_int_e10: 'dk_end_dowry',
  dk_end_bankrupt: 'dk_go_bankrupt',
};

export function assetUrl(
  path: string,
  baseUrl: string = import.meta.env.BASE_URL || '/'
): string {
  if (!path) return path;
  if (/^(?:https?:|data:|blob:)/i.test(path)) return path;
  const normalizedBase = baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`;
  if (normalizedBase !== '/' && path.startsWith(normalizedBase)) return path;
  const clean = path.replace(/^\/+/, '');
  return `${normalizedBase}${clean}`;
}

export function resolveNpcImage(character: string, keyword: string): string | undefined {
  const who = character.trim().toLowerCase() as keyof typeof NPC_ASSETS;
  const map = NPC_ASSETS[who];
  if (!map) return undefined;
  const norm = keyword.trim().toLowerCase();
  if (map[norm]) return assetUrl(map[norm]);
  const underscored = norm.replace(/\s+/g, '_');
  if (map[underscored]) return assetUrl(map[underscored]);
  // Fuzzy prefix/substring fallback so slightly different LLM phrasing still displays a sprite
  const keys = Object.keys(map);
  const partial = keys.find((k) => k.includes(norm) || norm.includes(k));
  const raw = partial ? map[partial] : map['standing'] ?? Object.values(map)[0];
  return raw ? assetUrl(raw) : undefined;
}

export function resolveSceneAssetKey(key: string): string | undefined {
  let current = key.trim().toLowerCase();
  if (!current) return undefined;
  if (SCENE_ASSETS[current]) return current;

  const visited = new Set<string>();
  for (let i = 0; i < 6; i++) {
    if (visited.has(current)) break;
    visited.add(current);
    const next = SCENE_ASSET_ALIASES[current];
    if (!next) break;
    current = next.toLowerCase();
    if (SCENE_ASSETS[current]) return current;
  }
  return undefined;
}

export function resolveSceneAsset(key: string): string | undefined {
  const resolved = resolveSceneAssetKey(key);
  return resolved ? assetUrl(SCENE_ASSETS[resolved]) : undefined;
}
